/* cppi::ffd7c672453ff93ef9afd43c9bed709779b01b7027fe8e74f0088538ffe3e512 */
select business_date as date_, security_id, 'SP500_45' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-17' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'SP500_45_GR_USD_0_0' and security_id is not null

/* cppi::1401096d96ceaede6a775dacf89b80fd229cae4e5028fdc8c70d9b08883d3578 */
/* QuickSight bd80a602-5e15-4d76-917d-c7f494cde100 */
SELECT "dummy_value"
FROM (select 'Coming Soon' as dummy_value) AS "finsights_capital_dummy"

/* cppi::70f98601cad8ced566178a5d2d270e52753cb42e030c6d7b71f24437115381a5 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-11' and end_date = '2025-04-11')
and start_date = '2025-04-11' and end_date = '2025-04-11'

